using System.Globalization;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.EntityFrameworkCore;
using RelayPulse.Api.Data;
using RelayPulse.Core.Pulse;
using RelayPulse.Core.Statistics;

namespace RelayPulse.Api.Pulse;

public static class PulseEndpoints
{
    public const string InvalidWeek = "pulse.invalid_week";
    public const string AccountNotFound = "pulse.account_not_found";

    public static IEndpointRouteBuilder MapPulse(this IEndpointRouteBuilder app)
    {
        app.MapGet("/api/accounts/{id:int}/pulse", GetPulseAsync);
        return app;
    }

    private static async Task<Results<Ok<PulseResponse>, ProblemHttpResult>> GetPulseAsync(
        int id,
        string? week,
        RelayDbContext db,
        PulseQuery query,
        ILoggerFactory loggerFactory,
        CancellationToken cancellationToken)
    {
        var logger = loggerFactory.CreateLogger(typeof(PulseEndpoints).FullName!);
        DateOnly? requested = null;
        if (week is not null)
        {
            if (!DateOnly.TryParseExact(week, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
            {
                return Problem(400, InvalidWeek, $"'{week}' is not a date in YYYY-MM-DD form.");
            }

            requested = parsed;
        }

        var account = await db.Accounts.AsNoTracking().SingleOrDefaultAsync(a => a.Id == id, cancellationToken);
        if (account is null)
        {
            return Problem(404, AccountNotFound, $"No account with id {id}.");
        }

        // Complete weeks come from week_buckets, which is built from the global MIN/MAX(occurred_at):
        // the default is the last complete week of the data, never of the wall clock.
        var completeWeeks = await db.WeekBuckets.AsNoTracking()
            .Where(b => b.Timezone == account.Timezone && b.IsComplete)
            .OrderBy(b => b.WeekStartLocal)
            .Select(b => b.WeekStartLocal)
            .ToListAsync(cancellationToken);

        if (completeWeeks.Count == 0)
        {
            // No data loaded at all: only an explicit week is a bad parameter.
            if (requested is not null)
            {
                return Problem(400, InvalidWeek, "There are no complete weeks of data yet.");
            }

            var nothing = new PulseRow(null, 0, Verdict.InsufficientHistory, null, null, null, null, 0, []);
            return TypedResults.Ok(new PulseResponse(account.Id, account.Name, account.Timezone, null, "empty", nothing, []));
        }

        var target = requested ?? completeWeeks[^1];
        var index = completeWeeks.BinarySearch(target);
        if (index < 0)
        {
            return Problem(400, InvalidWeek,
                $"{target:yyyy-MM-dd} is not the Monday of a complete week; choose a Monday from " +
                $"{completeWeeks[0]:yyyy-MM-dd} to {completeWeeks[^1]:yyyy-MM-dd}.");
        }

        // All complete weeks up to the target, not just the baseline window: the location list and
        // "has any events" are properties of the whole history (PulseBuilder.Build's contract).
        var rows = await query.RunAsync(id, completeWeeks[0], target, cancellationToken);
        var report = PulseBuilder.Build(completeWeeks, target, rows);

        logger.LogInformation("Pulse: served {AccountId} week {Week}", id, target.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));

        return TypedResults.Ok(new PulseResponse(
            account.Id,
            account.Name,
            account.Timezone,
            new PulsePeriod(
                target,
                target.AddDays(6),
                requested is null,
                completeWeeks[0],
                completeWeeks[^1],
                index > 0 ? completeWeeks[index - 1] : null,
                index < completeWeeks.Count - 1 ? completeWeeks[index + 1] : null),
            report.HasEvents ? "ok" : "empty",
            PulseRow.From(report.Account),
            report.Locations.Select(PulseRow.From).ToList()));
    }

    private static ProblemHttpResult Problem(int status, string code, string detail) =>
        TypedResults.Problem(statusCode: status, title: code, detail: detail);
}
using RelayPulse.Core.Pulse;
using RelayPulse.Core.Statistics;

namespace RelayPulse.Api.Pulse;

/// <param name="Period">Null only when no data has been loaded at all.</param>
/// <param name="State"><c>ok</c>, or <c>empty</c> when the account has no events to judge.</param>
public sealed record PulseResponse(
    int AccountId,
    string AccountName,
    string Timezone,
    PulsePeriod? Period,
    string State,
    PulseRow Account,
    IReadOnlyList<PulseRow> Locations);

/// <param name="WeekEnd">Sunday, inclusive, in the account's timezone.</param>
/// <param name="PreviousWeek">Previous complete week, null at the start of the window.</param>
/// <param name="NextWeek">Next complete week, null at the last complete week.</param>
public sealed record PulsePeriod(
    DateOnly WeekStart,
    DateOnly WeekEnd,
    bool IsDefault,
    DateOnly FirstCompleteWeek,
    DateOnly LastCompleteWeek,
    DateOnly? PreviousWeek,
    DateOnly? NextWeek);

/// <param name="Location">Null on the account row.</param>
/// <param name="Lambda">Expected count from the trimmed 12-week baseline; null with insufficient history.</param>
/// <param name="PLow">P(X ≤ count).</param>
/// <param name="PHigh">P(X ≥ count).</param>
public sealed record PulseRow(
    string? Location,
    int Count,
    Verdict Verdict,
    double? Lambda,
    CountBand? Band,
    double? PLow,
    double? PHigh,
    int BaselineWeeks,
    IReadOnlyList<TypeSplit> ByType)
{
    public static PulseRow From(SeriesPulse s) => new(
        s.Location,
        s.Count,
        s.Assessment.Verdict,
        s.Assessment.Lambda,
        s.Assessment.Band,
        s.Assessment.PLow,
        s.Assessment.PHigh,
        s.BaselineWeeks,
        s.ByType);
}
using RelayPulse.Core.Statistics;

namespace RelayPulse.Core.Pulse;

/// <summary>
/// One aggregation row: events in one account-local week, at one grain, split by type and outcome.
/// <see cref="Location"/> is null on account-grain rows (the second GROUPING SETS set); the column
/// is NOT NULL in the schema, so null is unambiguous.
/// </summary>
public sealed record WeeklyCount(DateOnly WeekStart, string? Location, string EventType, string? Outcome, int Events);

/// <param name="HasEvents">False when the account has no events in any complete week up to the target.</param>
public sealed record PulseReport(bool HasEvents, SeriesPulse Account, IReadOnlyList<SeriesPulse> Locations);

/// <summary>The judged week for one series: the whole account (<see cref="Location"/> null) or one location.</summary>
/// <param name="BaselineWeeks">Prior complete weeks the baseline drew on (at most 12, before trimming).</param>
public sealed record SeriesPulse(
    string? Location,
    int Count,
    int BaselineWeeks,
    Assessment Assessment,
    IReadOnlyList<TypeSplit> ByType);

/// <param name="Outcomes">Per-type outcome counts; a NULL outcome is keyed <see cref="PulseBuilder.UnspecifiedOutcome"/>.</param>
public sealed record TypeSplit(string EventType, int Count, IReadOnlyDictionary<string, int> Outcomes);
