import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { Observable } from 'rxjs';

// Wire shapes of GET /api/accounts and GET /api/accounts/{id}/pulse. Dates are YYYY-MM-DD, account-local.

export interface AccountSummary {
  id: number;
  name: string;
  timezone: string;
}

export type Verdict = 'normal' | 'above' | 'below' | 'not_enough_volume' | 'insufficient_history';

export interface TypeSplit {
  eventType: string;
  count: number;
  /** A NULL outcome arrives keyed "unspecified". */
  outcomes: Record<string, number>;
}

export interface PulseRow {
  location: string | null;
  count: number;
  verdict: Verdict;
  lambda: number | null;
  band: { lo: number; hi: number } | null;
  pLow: number | null;
  pHigh: number | null;
  baselineWeeks: number;
  byType: TypeSplit[];
}

export interface PulsePeriod {
  weekStart: string;
  weekEnd: string;
  isDefault: boolean;
  firstCompleteWeek: string;
  lastCompleteWeek: string;
  previousWeek: string | null;
  nextWeek: string | null;
}

export interface Pulse {
  accountId: number;
  accountName: string;
  timezone: string;
  /** Null only when no data has been loaded at all. */
  period: PulsePeriod | null;
  state: 'ok' | 'empty';
  account: PulseRow;
  /** Ranked by the server; never re-sorted here. */
  locations: PulseRow[];
}

export function accountsUrl(): string {
  return '/api/accounts';
}

export function pulseUrl(accountId: string | number, week?: string): string {
  const base = `/api/accounts/${encodeURIComponent(accountId)}/pulse`;
  return week ? `${base}?week=${encodeURIComponent(week)}` : base;
}

@Injectable({ providedIn: 'root' })
export class PulseApi {
  private readonly http = inject(HttpClient);

  accounts(): Observable<AccountSummary[]> {
    return this.http.get<AccountSummary[]>(accountsUrl());
  }

  pulse(accountId: string | number, week?: string): Observable<Pulse> {
    return this.http.get<Pulse>(pulseUrl(accountId, week));
  }
}
EOF
cat > src/app/pulse/route-guards.ts <<'EOF'
import { inject } from '@angular/core';
import { CanActivateFn, RedirectCommand, Router } from '@angular/router';
import { catchError, map, of } from 'rxjs';

import { PulseApi } from './pulse-api';

/** '' → /accounts/{first account}. */
export const firstAccount: CanActivateFn = () => {
  const router = inject(Router);
  return inject(PulseApi)
    .accounts()
    .pipe(
      map((accounts) =>
        accounts.length > 0
          ? new RedirectCommand(router.createUrlTree(['/accounts', accounts[0].id]), { replaceUrl: true })
          : true,
      ),
      catchError(() => of(true)),
    );
};

/**
 * /accounts/:id → /accounts/:id/week/{default week}, replacing the URL. The default week is the
 * server's (last complete week of the data), never computed here. If the server can't name one
 * (unknown account, no data loaded), the view renders that state from the same request.
 */
export const defaultWeek: CanActivateFn = (route) => {
  const router = inject(Router);
  const id = route.paramMap.get('id')!;
  return inject(PulseApi)
    .pulse(id)
    .pipe(
      map((pulse) =>
        pulse.period
          ? new RedirectCommand(router.createUrlTree(['/accounts', id, 'week', pulse.period.weekStart]), {
              replaceUrl: true,
            })
          : true,
      ),
      catchError(() => of(true)),
    );
};
EOF

