          <th scope="col">Events</th>
          <th scope="col">Typical range</th>
          <th scope="col">Verdict</th>
          <th scope="col">By type</th>
        </tr>
      </thead>
      <tbody>
        @for (row of p.locations; track row.location) {
          <tr>
